using Captovix;
using System.Text.Json;
int count=0;void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
var form=new EditorDocument{OriginalWidth=500,OriginalHeight=300};var scan=new ScanElement{Bounds=new(30,40,160,40),Kind=MockupKind.Button,Text="Lưu dữ liệu",Include=true,FontFamily="Times New Roman",FontSize=14,FontItalic=true,FontBold=true,Colors=new("#FFFFFF","#2563EB","#FFFFFF",1)};
var source=JsonSerializer.Serialize(scan);var parts=ElementScan.Prepare(form,[scan],new(0,0,500,300));Check(parts.Count==2,"UI-only button with a name produces two layers without OCR runs");Check(JsonSerializer.Serialize(scan)==source,"Preparing split layers never mutates reviewed candidates");var body=parts.Single(a=>a.Mockup!.Type==MockupKind.Button);var caption=parts.Single(a=>a.Mockup!.Type==MockupKind.Label);Check(body.Text.Length==0&&caption.Text==scan.Text,"Only caption owns button text");Check(parts.IndexOf(caption)>parts.IndexOf(body)&&caption.GroupId==body.GroupId,"Caption is above the control and shares its leaf group");Check(caption.FontFamily=="Times New Roman"&&caption.FontSize==14&&caption.Bold&&caption.Italic,"Split caption retains captured typeface and formatting");form.Annotations.AddRange(parts);form.Validate(500,300,"");string textBefore=JsonSerializer.Serialize(caption);MockupEditing.Apply(form,body.Id,MockupEditing.Read(body) with{Fill="#EF3F51"});Check(JsonSerializer.Serialize(form.Annotations.Single(a=>a.Id==caption.Id))==textBefore,"Recolouring a button never changes its caption properties");var newBody=form.Annotations.Single(a=>a.Id==body.Id);var bodyBefore=JsonSerializer.Serialize(newBody);MockupEditing.Apply(form,caption.Id,MockupEditing.Read(caption) with{Text="Xác nhận"});Check(JsonSerializer.Serialize(form.Annotations.Single(a=>a.Id==body.Id))==bodyBefore,"Editing caption text never changes button properties");
var multi=new ScanElement{Id=Guid.NewGuid().ToString("N"),Bounds=scan.Bounds,Kind=MockupKind.Button,Include=true,Text="Line1\nLine2",TextRuns=[new(new(40,44,130,12),"Line1","#FFFFFF"),new(new(40,60,130,12),"Line2","#FFFFFF")]};Check(ElementScan.Prepare(new(){OriginalWidth=500,OriginalHeight=300},[multi],new(0,0,500,300)).Count==2,"OCR multi-line button caption is one label layer above a single body");
var settings=new AppearanceSettings(AccentGradient:true,AccentEnd:"#00AABB",IconUsesAccent:false,IconColor:"#FF7722",IconGradient:true,IconEnd:"#EEDD22",GradientAngle:135);settings.Validate();Check(JsonSerializer.Deserialize<AppearanceSettings>(JsonSerializer.Serialize(settings))==settings,"Independent icon/accent gradients survive settings roundtrip");var old=JsonSerializer.Deserialize<AppearanceSettings>("{\"Mode\":2,\"Accent\":\"#2563EB\",\"Schema\":1}")!;old.Validate();Check(old.Mode==AppearanceMode.Dark&&old.IconUsesAccent&&!old.AccentGradient,"V1.45 appearance settings remain compatible");foreach(var bad in new[]{settings with{IconEnd="bad"},settings with{GradientAngle=double.NaN}}){bool rejected=false;try{bad.Validate();}catch{rejected=true;}Check(rejected,"Invalid gradient settings are rejected before saving");}
Console.WriteLine($"{count} Mockup reliability logic checks passed.");
